    this.createChildSession,
    this.sink,
    this.source,
    this.messaging,
    this.wakeProcess,
    this.homeDir,
    this.selfId = 'main',
    this.maxPendingMessages = 16,
    this.maxReplyChars = 8000,
    this.clock = _systemUtcClock,
