            (cli) => cli.closeObligation(ids.first, 'emergency'),
            (cli) => cli.closeObligation(ids.first, 'done'),
            (cli) => cli.closeObligation(ids.last, 'superseded'),
          ],
          textTurn('ack four'),
        ),
