    final stream = _ProbedStream([
      // A plain reply: the rule classifier ingests nothing.
      (const [], textTurn('plain reply')),
      (const [], textTurn('ack')),
      ([(cli) => cli.closeObligation('obl-gone', 'done')], textTurn('ack two')),
