      final throttle = LedgerSnapshotThrottle(
        minInterval: const Duration(seconds: 30),
        clock: () => now,
      );
      expect(throttle.shouldPersistNow(), isTrue);
      throttle.confirmPersisted();
      now = now.add(const Duration(seconds: 31));
      expect(
