      const jobCount = 4;
      final io = FakeCliIO();
      final shell = _ThrottleShell();
      final env = MemoryExecutionEnv(cwd: '/work', shell: shell);
      final stream = _JobSpawnerStream(jobCount: jobCount);
      final cli = AgentCli(
