      // carries the first request — this state is persisted for real.
      final midRun = snapshots.where(
        (snapshot) => snapshot.any(
          (row) =>
              row['id'] == 'scout' &&
              row['status'] == 'running' &&
              (row['requests'] as num? ?? 0) > 0,
        ),
      );
