final class _ProbedStream {
  _ProbedStream(this.turns);

  /// One turn per model call; probes run before the turn's events.
  final List<
    (List<Future<String> Function(AgentCli)>, List<AssistantMessageEvent>)
  >
  turns;

  AgentCli? cli;

  int get calls => _calls;
