        'coalesce into ONE snapshot; the flush lands the final state; a '
        'second flush is a deduped no-op', () async {
      final manager = buildThrottledManager();
      for (var i = 1; i <= 4; i++) {
        await manager.register(
          id: 'child-$i',
          name: 'child-$i',
          agentType: 'task',
          task: 'task $i',
