        'resurrect from a stale snapshot)', () async {
      final manager = buildThrottledManager();
      await manager.register(
        id: 'child-1',
        name: 'child-1',
        agentType: 'task',
        task: 'survey',
      );
      await manager.dispose('child-1');
      expect(snapshots, hasLength(2));
      expect(snapshots.last, isEmpty);
    });

